<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {Plus,ArrowLeft,Download,Braces} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document} from '../domain/local-contract'
import {importRegexRule,exportRegexRule,validateRegexRule,applyRegex,type RegexRule,type RegexAsset,type RegexTrace} from '../prompt-runtime/regex'
import type {MacroContext} from '../prompt-runtime/macros'
const store=useLocal(),rows=ref<Document<RegexAsset>[]>([]),editing=ref<RegexRule|null>(null),editingId=ref(''),revision=ref(0),bindings=ref<Document<{regexIds:string[]}>|null>(null),search=ref(''),error=ref(''),busy=ref(false),sample=ref('灯塔亮了，你到了吗？'),display=ref(''),prompt=ref(''),trace=ref<RegexTrace[]>([]),placement=ref(2),controller=new AbortController();let disposed=false,testController:AbortController|null=null
const visible=computed(()=>rows.value.filter(row=>row.value.name.toLowerCase().includes(search.value.toLowerCase())))
async function load(){const vault=store.vault;if(!vault)return;const [values,global]=await Promise.all([vault.list<RegexAsset>('settings'),vault.read<{regexIds:string[]}>('settings:regex-bindings')]);if(disposed||store.vault!==vault)return;rows.value=values.filter(row=>row.value.assetType==='regex');bindings.value=global}
function leaveEditor(){testController?.abort();testController=null;editing.value=null;display.value='';prompt.value='';trace.value=[]}
function edit(row?:Document<RegexAsset>){leaveEditor();editing.value=row?JSON.parse(JSON.stringify(row.value.rule)):importRegexRule('{"scriptName":"新正则","findRegex":"灯塔","replaceString":"**{{match}}**","placement":[2],"markdownOnly":true}');editingId.value=row?.id||'regex:'+crypto.randomUUID();revision.value=row?.revision||0;error.value=''}
async function save(){const vault=store.vault;if(!vault||!editing.value||busy.value)return;busy.value=true;try{validateRegexRule(editing.value);exportRegexRule(editing.value);await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:editingId.value,expectedRevision:revision.value,value:{assetType:'regex',name:editing.value.name,rule:editing.value}}],controller.signal);if(disposed||store.vault!==vault)return;editing.value=null;await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function bind(row:Document<RegexAsset>){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{const ids=bindings.value?.value.regexIds||[];await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:'settings:regex-bindings',expectedRevision:bindings.value?.revision||0,value:{regexIds:ids.includes(row.id)?ids.filter(id=>id!==row.id):[...ids,row.id]}}],controller.signal);await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function test(){if(!editing.value)return;testController?.abort();const control=new AbortController();testController=control;error.value='';try{const now=new Date(),macros:MacroContext={char:'角色',user:'读者',persona:'',description:'',personality:'',scenario:'',mesExamples:'',input:sample.value,lastMessage:sample.value,lastUserMessage:sample.value,lastCharMessage:'',date:now.toISOString().slice(0,10),time:now.toISOString().slice(11,19),seed:'regex-preview'},row:Document<RegexAsset>={id:editingId.value,revision:revision.value||1,kind:'settings',updatedAt:'',value:{assetType:'regex',name:editing.value.name,rule:editing.value}},options={placement:placement.value,depth:0,speakerId:'preview',edited:false,macros},a=await applyRegex([row],sample.value,{...options,channel:'display'},control.signal),b=await applyRegex([row],sample.value,{...options,channel:'prompt'},control.signal);if(disposed||testController!==control)return;display.value=a.text;prompt.value=b.text;trace.value=[...a.trace,...b.trace]}catch(e){if(!control.signal.aborted&&!disposed)error.value=(e as Error).message}}
async function upload(event:Event){const input=event.target as HTMLInputElement,vault=store.vault;if(!vault||busy.value)return;busy.value=true;const failures:string[]=[];try{const files=Array.from(input.files||[]);if(files.length>64)throw new Error('一次最多导入 64 条正则');for(const file of files){controller.signal.throwIfAborted();try{if(file.size>1024*1024)throw new Error("正则文件超过 1 MiB");const rule=importRegexRule(await file.text());await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:'regex:'+crypto.randomUUID(),expectedRevision:0,value:{assetType:'regex',name:rule.name,rule}}],controller.signal)}catch(e){if(controller.signal.aborted)throw e;failures.push(file.name+'：'+(e as Error).message)}}await load();error.value=failures.join('；')}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false;input.value=''}}
function download(row:Document<RegexAsset>){try{const url=URL.createObjectURL(new Blob([exportRegexRule(row.value.rule)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=row.value.name+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=(e as Error).message}}
function trims(event:Event){if(editing.value)editing.value.trim=(event.target as HTMLTextAreaElement).value.split('\n').filter(Boolean)}
onMounted(()=>void load().catch(e=>error.value=(e as Error).message));onUnmounted(()=>{disposed=true;controller.abort();testController?.abort()})
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">TAVERN ASSETS</span><h1>{{editing?editing.name:'正则'}}</h1></div><div class="final-page-actions"><button v-if="editing" @click="leaveEditor"><ArrowLeft :size="18"/>返回</button><button v-else class="final-primary" @click="edit()"><Plus :size="18"/>新建</button></div></div><p v-if="error" role="alert" class="final-error">{{error}}</p>
<form v-if="editing" class="final-card-form" @submit.prevent="save"><label>名称<input v-model="editing.name" required maxlength="200"></label><label>查找正则<input v-model="editing.pattern" maxlength="512" spellcheck="false" required></label><label>替换内容<textarea v-model="editing.replacement" maxlength="20000" spellcheck="false" rows="4"></textarea></label><div class="final-grid-actions"><label class="final-check"><input v-model="editing.enabled" type="checkbox">启用</label><label class="final-check"><input v-model="editing.display" type="checkbox">改变显示</label><label class="final-check"><input v-model="editing.prompt" type="checkbox">改变送模文本</label><label class="final-check"><input v-model="editing.runOnEdit" type="checkbox">处理编辑候选</label></div><fieldset><legend>作用内容</legend><label class="final-check"><input v-model="editing.placements" :value="1" type="checkbox">用户消息</label><label class="final-check"><input v-model="editing.placements" :value="2" type="checkbox">角色消息</label><label class="final-check"><input v-model="editing.placements" :value="5" type="checkbox">世界书</label></fieldset><details><summary>更多设置</summary><label>查找中的宏<select v-model.number="editing.macroMode"><option :value="0">保留原样</option><option :value="1">替换</option><option :value="2">替换并转义</option></select></label><label>去除匹配内容<input :value="editing.trim.join('\n')" @change="trims"></label><div class="final-grid-row"><label>最小深度<input v-model.number="editing.minDepth" type="number" min="-1" max="10000" placeholder="不限"></label><label>最大深度<input v-model.number="editing.maxDepth" type="number" min="-1" max="10000" placeholder="不限"></label></div></details>
<section class="final-import-panel"><h2>预览</h2><label>原始文本<textarea v-model="sample" maxlength="200000" rows="4"></textarea></label><label>预览内容<select v-model.number="placement"><option :value="1">用户消息</option><option :value="2">角色消息</option><option :value="5">世界书</option></select></label><button type="button" @click="test">运行预览</button><div v-if="trace.length" class="final-grid-row"><div><h3>显示文本</h3><pre class="final-task-prose">{{display}}</pre></div><div><h3>送模文本</h3><pre class="final-task-prose">{{prompt}}</pre></div></div><small v-for="(item,index) in trace" :key="index" class="final-subtle">{{item.channel==='display'?'显示':'送模'}} · {{item.reason}} · {{item.matches}} 处</small></section><button class="final-primary" :disabled="busy">保存正则</button></form>
<template v-else><div class="final-page-actions"><RouterLink to="/local/characters" class="final-text-link">返回角色</RouterLink><RouterLink to="/local/lorebooks" class="final-text-link">世界书</RouterLink></div><label class="final-import-panel">导入正则 JSON<input type="file" multiple accept=".json" :disabled="busy" @change="upload"></label><label v-if="rows.length" class="final-search">搜索正则<input v-model="search" type="search"></label><div v-if="!rows.length" class="final-empty"><Braces :size="40"/><h2>让文字按你的方式呈现</h2><button class="final-primary" @click="edit()">创建正则</button></div><div class="final-collection-grid"><article v-for="row in visible" :key="row.id" class="final-character-card"><Braces :size="28"/><h2>{{row.value.name}}</h2><span class="final-subtle">{{row.value.rule.enabled?'已启用':'已停用'}} · 版本 {{row.revision}}</span><div class="final-grid-actions"><button @click="edit(row)">编辑</button><button class="final-icon-button" :aria-label="'导出'+row.value.name" @click="download(row)"><Download :size="18"/></button></div><button :disabled="busy" :aria-pressed="!!bindings?.value.regexIds.includes(row.id)" @click="bind(row)">{{bindings?.value.regexIds.includes(row.id)?'移除全局绑定':'绑定所有对话'}}</button></article></div></template></section></template>
